-- StrengthProgram (3 rows)
INSERT OR IGNORE INTO "StrengthProgram" ("id", "key", "variantId", "name", "authorship", "cursorKind", "initialCursor", "citationAuthor", "citationWork", "citationYear", "citationLocator", "provenanceNote", "createdAt", "updatedAt") VALUES ('prog_greyskull_lp_base', 'greyskull-lp', 'base', 'GreySkull LP', 'system', 'alternatingDays', '{"kind":"alternatingDays","nextDayId":"A"}', 'John “Johnny Pain” Sheaffer', 'Greyskull LP (primary is a paid e-book; secondary consensus used)', NULL, 'The 2×5 + 1×5+ template and its AMRAP progression', 'GreySkull’s primary source is a paid e-book. The ≥ 10-rep double increment, the day composition and the ~10 % cut are reverse-engineered from secondary sources, and the cut percentage has no trial behind it.', 1787011200000, 1787011200000);
INSERT OR IGNORE INTO "StrengthProgram" ("id", "key", "variantId", "name", "authorship", "cursorKind", "initialCursor", "citationAuthor", "citationWork", "citationYear", "citationLocator", "provenanceNote", "createdAt", "updatedAt") VALUES ('prog_starting_strength_phase1', 'starting-strength', 'phase-1', 'Starting Strength', 'system', 'alternatingDays', '{"kind":"alternatingDays","nextDayId":"A"}', 'Mark Rippetoe', 'Starting Strength: Basic Barbell Training / startingstrength.com', 2011, 'The novice linear progression and its resets', 'The reset cuts ~10 % (the press 8–10 %, low end taken) and reduces the increment — both published, and the percentages are program convention with no trial behind them. How many misses precede a reset is not published; the family’s three is used.', 1787011200000, 1787011200000);
INSERT OR IGNORE INTO "StrengthProgram" ("id", "key", "variantId", "name", "authorship", "cursorKind", "initialCursor", "citationAuthor", "citationWork", "citationYear", "citationLocator", "provenanceNote", "createdAt", "updatedAt") VALUES ('prog_stronglifts_5x5_basic', 'stronglifts-5x5', 'basic', 'StrongLifts 5×5', 'system', 'alternatingDays', '{"kind":"alternatingDays","nextDayId":"A"}', 'Mehdi Hadim', 'StrongLifts 5×5 (stronglifts.com, support.stronglifts.com)', NULL, 'Progression, failure and plateau articles; retrieved 2026-08-13', 'Increments and the three-session −10 % Stall Cut are StrongLifts’ own published defaults. The percentage is program convention and is supported by no trial. The 5×5 → 3×5 → 1×5 ladder is not StrongLifts’ rule and is not implemented. Row and deadlift start at the low end of the published 30–40 kg range.', 1787011200000, 1787011200000);

