-- The progression key's second half, stated on an athlete's own lift state where
-- a run of these three programs already left it NULL.
--
-- Not a number: `currentWorkingWeightKg`, the training max, the Stall Count and
-- both histories are untouched. It states the half of the key the rule now
-- states, so a run started before this migration keeps matching its rule instead
-- of silently ceasing to progress.
--
-- Bounded three ways and idempotent: only rows whose `equipment` IS NULL, only
-- the five lifts these three programs progress, only instances of these three
-- programs — and only where no sibling row already holds `'barbell'` for the same
-- instance and lift, because `(instanceId, exerciseId, equipment)` is unique and
-- SQLite would refuse the second one. A second run matches nothing.
UPDATE "ProgramLiftState" SET "equipment" = 'barbell'
WHERE "equipment" IS NULL
  AND "exerciseId" IN ('ex_bb_back_squat', 'ex_bb_bench', 'ex_bb_row', 'ex_bb_ohp', 'ex_bb_deadlift')
  AND "instanceId" IN (SELECT "id" FROM "ProgramInstance" WHERE "programId" IN ('prog_stronglifts_5x5_basic', 'prog_starting_strength_phase1', 'prog_greyskull_lp_base'))
  AND NOT EXISTS (
    SELECT 1 FROM "ProgramLiftState" AS "sibling"
    WHERE "sibling"."instanceId" = "ProgramLiftState"."instanceId"
      AND "sibling"."exerciseId" = "ProgramLiftState"."exerciseId"
      AND "sibling"."equipment" IS 'barbell'
  );
